    EXPECT_EQ(kOk, result);
    // After insert, cx would be 20 - SOFT_MARGIN + 1
    // pmeditor_adjust_viewport should have been called
    EXPECT_LT(self->cx, 20 - SOFT_MARGIN + 1);  // Adjusted
    EXPECT_GT(self->px, 0);  // Viewport scrolled
