    self->py = 0;
    self->cy = self->height - 3;
    self->txtp = pmeditor_start_of_line_n(self, self->py + self->cy) + self->cx;

    const int old_cy = self->cy;
    const int old_py = self->py;

    MmResult result = pmeditor_cmd_down(self);

    EXPECT_EQ(kOk, result);
    // Should scroll
